(3307854, 458465, 72835, '<td valign="top">Good display of citrus good job</td>', 'Good display of citrus good job', '2007-01-31 11:56:33.000000', NULL, 1),
(3307859, 459038, 68256, '<td valign="top">I think the viewpoint is excellent, and the composition is great.  I wished there was more seperation between the subject and background via color or contrast.  Also the lighting seems maybe a little harsh killing the form.   One other negative for me is that jpeg artifects are very evident around the frog.  The size of your jpeg is 82,433 kb so you could have used a higher quality jpeg (get as close to 150 as you can).  All just my opinion of course and overall I like the shot.</td>', 'I think the viewpoint is excellent, and the composition is great.  I wished there was more seperation between the subject and background via color or contrast.  Also the lighting seems maybe a little harsh killing the form.   One other negative for me is that jpeg artifects are very evident around the frog.  The size of your jpeg is 82,433 kb so you could have used a higher quality jpeg (get as close to 150 as you can).  All just my opinion of course and overall I like the shot.', '2007-01-31 11:57:38.000000', NULL, 1),
(3307861, 460643, 65779, '<td valign="top">Subtle but good</td>', 'Subtle but good', '2007-01-31 11:57:58.000000', NULL, 1),
