INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3338126, 459304, 70607, '<td valign="top">A-ha....thought this was a Whiterook photo, nice one!!</td>', 'A-ha....thought this was a Whiterook photo, nice one!!', '2007-02-07 05:19:35.000000', NULL, 0),
(3338282, 461113, 28742, '<td valign="top">LOL! Excellent!</td>', 'LOL! Excellent!', '2007-02-07 06:38:07.000000', NULL, 0),
(3338287, 458186, 28742, '<td valign="top">Sweet! Looks like you''re cutting down. ;-) Congrats on a great score in the table shot challenge!</td>', 'Sweet! Looks like you''re cutting down. ;-) Congrats on a great score in the table shot challenge!', '2007-02-07 06:40:37.000000', NULL, 0),
(3338315, 460643, 48471, '<td valign="top">Thanks for having a look at this photo. One of Umberto Eco''s book has a similar photo on the cover, but that''s color. I decided for a different look, that''s black and white and with books closer to the lens (filling the frame). The dark becoming light is supposed to show what Eco does: he shines the dark ages, doesn''t he? I don''t know whether the dark is so extreme; it''s black, but not so much, and only for a small part of the photo.<br/> <br/>Thanks to JPR for giving me something more than a ribbon!</td>', 'Thanks for having a look at this photo. One of Umberto Eco''s book has a similar photo on the cover, but that''s color. I decided for a different look, that''s black and white and with books closer to the lens (filling the frame). The dark becoming light is supposed to show what Eco does: he shines the dark ages, doesn''t he? I don''t know whether the dark is so extreme; it''s black, but not so much, and only for a small part of the photo. Thanks to JPR for giving me something more than a ribbon!', '2007-02-07 06:52:00.000000', NULL, 0),
(3338321, 460641, 62187, '<td valign="top">This is my pick for the ''You got Robbed'' photo...I was one of the two 10''s and I thought for sure it would be in the top 10. Just goes to show how much I know. Although I felt the focus could be better on the cup, I really liked the contrasting colors and the general ''feel'' of the photo. Keep up the good work!</td>', 'This is my pick for the ''You got Robbed'' photo...I was one of the two 10''s and I thought for sure it would be in the top 10. Just goes to show how much I know. Although I felt the focus could be better on the cup, I really liked the contrasting colors and the general ''feel'' of the photo. Keep up the good work!', '2007-02-07 06:56:35.000000', NULL, 0),
(3338331, 461524, 28029, '<td valign="top">Congratulations on your ribbon. Your entry was fun and well done. Great job.</td>', 'Congratulations on your ribbon. Your entry was fun and well done. Great job.', '2007-02-07 06:59:03.000000', NULL, 0),
